query:
mutation login($username: String!, $password: String!) {
  login(input: {username: $username, password: $password}) {
    __typename
    ... on SuccessLoginPayload {
      deviceRefreshToken
      __typename
    }
    ... on PartialSuspendedLoginPayload {
      leagueIds
      deviceRefreshToken
      __typename
    }
    ... on DeniedLoginPayload {
      reason
      __typename
    }
  }
}
